class Solution {
public:
    int totalNQueens(int n) {
        int count = 0;
        solve(0, n, 0, 0, 0, count);
        return count;
    }
private:
    void solve(int row, int n, int cols, int d1, int d2, int& count) {
        if (row == n) {
            count++;
            return;
        }
        for (int col = 0; col < n; col++) {
            int c = 1 << col;
            int p = 1 << (row - col + n - 1);
            int q = 1 << (row + col);
            if ((cols & c) || (d1 & p) || (d2 & q)) continue;
            solve(row + 1, n, cols | c, d1 | p, d2 | q, count);
        }
    }
};
